 "content": "def transform(grid):
    """Vertically align each colored object by its top edge, preserving x and shape."""
    h, w = len(grid), len(grid[0])
    cells = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                cells.setdefault(color, []).append((r, c))
    if not cells:
        return [row[:] for row in grid]
    target_top = min(r for pts in cells.values() for r, _ in pts)
    out = [[0] * w for _ in range(h)]
    for color, pts in cells.items():
        top = min(r for r, _ in pts)
        dr = target_top - top
        for r, c in pts:
            nr = r + dr
            if not (0 <= nr < h):
                raise ValueError('translated object exceeds grid')
            out[nr][c] = color
    return out
